"""Synthetic vectors generated by executing the school's unmodified encrypt.js."""
import base64
import pytest
from uestc_login.crypto import encrypt_password

@pytest.mark.parametrize('password,expected', [
('Example-123!', 'C5sV2ktEoPUVHc/EwB811XB+8Q2GjXiGjtyRUKn0tZBPMOykE8qp5hBRsHxL1HNb9wqYtOXhfT0V4GBzEezbb0ZA7bzO++jobduBSzHEMho='),
('密码🔒', 'C5sV2ktEoPUVHc/EwB811XB+8Q2GjXiGjtyRUKn0tZBPMOykE8qp5hBRsHxL1HNb9wqYtOXhfT0V4GBzEezbbyd11JBy/8hOKT1iENjcbt8='),
('a'*16, 'C5sV2ktEoPUVHc/EwB811XB+8Q2GjXiGjtyRUKn0tZBPMOykE8qp5hBRsHxL1HNb9wqYtOXhfT0V4GBzEezbb+Ba/8KhaJu5Ga0BMF4/M9vYdPoyBUIslA5CuIN13YHK'),
])
def test_matches_school_cryptojs(password,expected):
    assert encrypt_password(password,'0123456789abcdef',random=lambda n:'A'*n)==expected


def test_fresh_randomness_and_missing_key_fail_closed():
    a=encrypt_password('example','0123456789abcdef')
    b=encrypt_password('example','0123456789abcdef')
    assert a != b and len(base64.b64decode(a))==80
    with pytest.raises(ValueError):encrypt_password('example','')
